def count_eligible_accounts(prague_district_id):
    eligible_accounts = loan.merge(account, on='account_id')
    eligible_accounts = eligible_accounts[eligible_accounts['district_id'] == prague_district_id]
    return len(eligible_accounts)

import pandas as pd

def count_female_customers_before_1950_in_sokolow(df_client, df_district):
    # Filter clients based on gender, birth year, and district name
    filtered_clients = df_client[
        (df_client['gender'] == 'female') &
        (df_client['birth_date'].dt.year < 1950) &
        (df_client['district_id'].isin(df_district[df_district['A2'] == 'Sokolow']['district_id']))
    ]

    # Count the number of filtered clients
    return len(filtered_clients)

import pandas as pd

def find_account_open_date(transaction_amount, transaction_date):
    filtered_transactions = trans[(trans['amount'] == transaction_amount) & (trans['date'] == transaction_date)]
    if not filtered_transactions.empty:
        account_ids = filtered_transactions['account_id'].unique()
        account_info = account[account['account_id'].isin(account_ids)][['account_id', 'date']]
        return account_info.drop_duplicates().sort_values(by='date').head(1)['date']
    else:
        return None

def find_account_open_date(account_df, trans_df, account_id, amount, date):
    filtered_trans = trans_df[(trans_df['account_id'] == account_id) & 
                             (trans_df['amount'] == amount) & 
                             (trans_df['date'] == date)]
    if not filtered_trans.empty:
        return account_df.loc[account_df['account_id'] == account_id, 'date'].values[0]
    else:
        return None

import pandas as pd

def get_loan_account_opened_district(loan_date):
    # Filter the loan DataFrame to find the loan with the given date and status 'approved'
    loan_info = loan[loan['date'] == loan_date & loan['status'] == 'approved']

    if not loan_info.empty:
        # Get the account_id from the filtered loan information
        account_id = loan_info.iloc[0]['account_id']

        # Filter the account DataFrame to find the district_id associated with the account_id
        account_info = account[account['account_id'] == account_id]

        if not account_info.empty:
            # Return the district_id
            return account_info.iloc[0]['district_id']
        else:
            return None
    else:
        return None

