def get_district_for_client(client_df, district_df, client_id):
    client_info = client_df[client_df['client_id'] == client_id]
    if not client_info.empty and client_info['gender'].values[0] == 'female' and client_info['birth_date'].values[0] == '1976-01-29':
        district_id = client_info['district_id'].values[0]
        return district_df[district_df['district_id'] == district_id]['A2'].values[0]
    else:
        return None

def get_district_and_region(loan_id):
    # Assuming 'account' DataFrame has a column 'loan_id'
    district_info = account[account['loan_id'] == loan_id]
    if not district_info.empty:
        district_id = district_info.iloc[0]['district_id']
        district_row = district[district['district_id'] == district_id].iloc[0]
        return district_row['A2'], district_row['A3']
    else:
        return None, None

def get_loan_location(loan_id):
    loan_data = account[account['account_id'] == loan_id]
    if not loan_data.empty:
        district_info = district[district['district_id'] == loan_data['district_id'].values[0]]
        return district_info.iloc[0]['A2'], district_info.iloc[0]['A3']
    else:
        return None, None

