def count_credit_card_withdrawals_after_1995(trans_df):
    # Filter transactions for credit card withdrawals after 1995
    filtered_df = trans_df[(trans_df['type'] == 'credit card withdrawal') & (trans_df['date'].dt.year > 1995)]
    # Count the number of such transactions
    return len(filtered_df)

import pandas as pd

def count_credit_card_withdrawals_after_1995(trans):
    # Filter transactions for credit card withdrawals and dates after 1995
    filtered_transactions = trans[(trans['type'] == 'credit card withdrawal') & (trans['date'].str.contains('/96/'))]

    # Count the number of such transactions
    return len(filtered_transactions)

def count_credit_card_withdrawals_after_1995(trans_df):
    # Filter transactions where type is 'WT' (withdrawal) and date is after January 1, 1995
    filtered_trans = trans_df[(trans_df['type'] == 'WT') & (trans_df['date'].str.startswith('1996'))]
    return len(filtered_trans)

